// Builds one FCM v1 request body per registered device.
//
// CHANGE THIS: 'Write Alert' must be the exact name of the node in your
// workflow that writes the alert document to Firestore.
const ALERT_SOURCE_NODE = 'Write Alert';

// Wire values are lowercase snake_case (see PROJECT_STATE.md data contract).
const AR_PRIORITY = {
  urgent: 'عاجلة',
  high: 'عالية',
  medium: 'متوسطة',
  low: 'منخفضة',
};
const AR_DEPARTMENT = {
  sales: 'المبيعات',
  operations: 'العمليات',
  delivery: 'التوصيل',
  finance: 'المالية',
  support: 'الدعم',
  management: 'الإدارة',
};

const alert = $(ALERT_SOURCE_NODE).first().json;
const priority = String(alert.priority || '').toLowerCase();
const department = String(alert.department || '').toLowerCase();

// Priority and department ONLY. Never the customer's message text -- a
// notification body renders on a locked screen in full view of the room.
const title = 'تنبيه جديد';
const body = [AR_PRIORITY[priority] || 'تنبيه', AR_DEPARTMENT[department]]
  .filter(Boolean)
  .join(' · ');

return $input.all()
  .map((item) => {
    const d = item.json;
    // The native Firestore node returns flat fields; a raw REST call returns
    // Firestore's typed shape. Accept either so this survives a node swap.
    const token = d.token || d?.fields?.token?.stringValue || null;
    if (!token) return null;

    return {
      json: {
        token,
        payload: {
          message: {
            token,
            notification: { title, body },
            apns: { payload: { aps: { sound: 'default' } } },
            data: {
              alert_id: String(alert.alert_id ?? alert.id ?? ''),
              priority,
            },
          },
        },
      },
    };
  })
  .filter(Boolean);
